function about(ctx, cents2) {
  const abs = Math.abs(cents2);
  const step = abs >= 1e5 ? Math.pow(10, Math.floor(Math.log10(abs)) - 1) : 100;
  return formatMoney(Math.sign(cents2) * Math.round(abs / step) * step, ctx.world.currency);
}
function investmentsView(api, ctx, party, detail) {
  const holdings = visibleHoldings(api, ctx, party).map((id2) => holdingView(api, ctx, id2, detail, party)).filter((h) => h !== null);
  if (holdings.length === 0 && !api.feature(ctx, party, "investments"))
    return null;
  const year = dateAt(calendarOf(ctx.world), ctx.state.clock).year;
  const gains = gainsIn(ctx.state, party, year);
  const income = incomeIn(ctx.state, party, year);
  const held2 = new Set(holdings.map((h) => h.asset.id));
  const listed2 = listedAssets(ctx);
  const market = [...new Set([...Object.keys(configAssets(ctx.world)), ...listed2.keys()])].sort().flatMap((id2) => {
    const def = listed2.has(id2) && !own(configAssets(ctx.world), id2) ? true : readAssetDef(own(configAssets(ctx.world), id2));
    const a = def ? assetOf(ctx, id2) : null;
    if (!a || held2.has(id2) || listed2.get(id2) === party || a.class === "property" || a.class === "business_stake")
      return [];
    const company2 = listed2.get(id2);
    if (company2 !== undefined && !own(configAssets(ctx.world), id2) && hiddenFrom(ctx, party, company2))
      return [];
    if (a.option && (!api.feature(ctx, party, "options") || ctx.state.clock >= a.option.expiry))
      return [];
    return [{ asset: id2, label: a.label, class: a.class, symbol: a.symbol, price: priceOf3(ctx, a) }];
  });
  const tax = detail ? taxEstimate(api, ctx, party) : null;
  return {
    value: holdings.reduce((s, h) => s + h.value, 0),
    cost: holdings.reduce((s, h) => s + h.cost, 0),
    unrealised: holdings.reduce((s, h) => s + h.gain, 0),
    realised: detail ? gains.short + gains.long : 0,
    income: income.dividend + income.interest + income.profit,
    realisedShort: detail ? gains.short : 0,
    realisedLong: detail ? gains.long : 0,
    taxDue: tax ? { cents: tax.cents, at: dateText(ctx.world, tax.at) } : null,
    holdings,
    market,
    accounts: api.accountsOf(ctx, party, "spend").filter((a) => api.traitsOf(ctx, a)?.investment === true),
    index: indexView(ctx)
  };
}
function alertsFor(api, ctx, party) {
  const out = [];
  const day = 1440;
  for (const id2 of visibleHoldings(api, ctx, party)) {
    const a = assetOf(ctx, strOf(own(ctx.state.entities, id2)?.fields.asset));
    if (!a)
      continue;
    const qty = qtyOf(lotsOf(ctx, id2));
    if (a.option && a.option.expiry > ctx.state.clock && a.option.expiry - ctx.state.clock <= 7 * day)
      out.push({ tone: "warn", text: `${unitsWord(qty, "contract")} of ${a.label} expire ${dateText(ctx.world, a.option.expiry)}.` });
    if (a.bond && a.bond.maturity > ctx.state.clock && a.bond.maturity - ctx.state.clock <= 31 * day)
      out.push({ tone: "info", text: `${a.label} matures ${dateText(ctx.world, a.bond.maturity)}.` });
  }
  return out;
}
function unitsWord(qty, word) {
  return `${Math.round(qty * 1e4) / 1e4} ${word}${qty === 1 ? "" : "s"}`;
}
function summaryLines(api, ctx, who) {
  const out = [];
  const invested = holdingsWorth(api, ctx, who).assets;
  if (invested > 0)
    out.push(`Has about ${about(ctx, invested)} invested.`);
  for (const id2 of propertyIds(ctx.state)) {
    const share2 = api.shareOf(ctx.state, id2, who);
    if (share2 <= 0)
      continue;
    const owed = securedLoans(api, ctx.state, id2).reduce((a, l) => a + l.owed, 0);
    const part = share2 < 100 ? `a ${Math.round(share2)}% share of ` : "";
    out.push(`Owns ${part}${labelOf(ctx, id2)} (worth ${about(ctx, propertyValue(ctx.state, id2))}${owed > 0 ? `; ${about(ctx, owed)} left on the mortgage` : ""}).`);
  }
  const rent = monthlyRent(api, ctx, who);
  if (rent > 0)
    out.push(`Collects about ${about(ctx, rent)} a month in rent.`);
  for (const id2 of businessIds2(api, ctx)) {
    const share2 = api.shareOf(ctx.state, id2, who);
    if (share2 <= 0 || id2 === who)
      continue;
    const value = valuationOf2(api, ctx, id2);
    out.push(`Owns ${share2 < 100 ? `${Math.round(share2)}% of ` : ""}${labelOf(ctx, id2)} (${value.floored ? "the shares worth nothing: its net worth is below zero" : `the shares worth about ${about(ctx, Math.round(value.value * share2 / 100))}`}).`);
  }
  return out;
}
function registerAssets(r) {
  registerMarkets(r);
  registerHoldings(r);
  registerIncome(r);
  registerOptions(r);
  registerGains(r);
  registerProperty(r);
  registerStakes(r);
  r.core.effect({
    type: "economy.route",
    args: ["holding?", "property?", "business?", "to?", "party?", "by?"],
    gm: true,
    resolve: (a, ctx) => {
      const party = strOf(a.party) || ctx.world.pov;
      const to = strOf(a.to);
      const from = strOf(a.holding) || strOf(a.property) || strOf(a.business);
      const where = to === "" ? "back to its owners" : to === "reinvest" ? "to be reinvested" : `to ${labelOf(ctx, to)}`;
      const what = strOf(a.property) !== "" ? "rent" : strOf(a.business) !== "" ? "profits" : "dividends";
      return actAs(ctx, { by: strOf(a.by), party, power: strOf(a.property) !== "" ? "property.manage" : "money.manage", line: () => `Sent ${labelOf(ctx, from)}'s ${what} ${where}` }, () => {
        if (strOf(a.holding) !== "")
          return setRoute(r.api, ctx, party, strOf(a.holding), to);
        if (strOf(a.property) !== "")
          return setRentRoute(r.api, ctx, party, strOf(a.property), to);
        if (strOf(a.business) !== "")
          return setStakeRoute(r.api, ctx, party, strOf(a.business), to);
        return reject9("bad_route", "say which holding, property or business");
      });
    }
  });
  r.core.action({
    id: "route_distributions",
    label: "Route dividends, rent or profits",
    description: "Choose where dividends, rent or profits are paid: reinvested, or into an account.",
    pack: "economy",
    mechanical: true,
    params: {
      holding: { type: "ref", ref: "holding", optional: true },
      property: { type: "ref", ref: "property", optional: true },
      business: { type: "ref", ref: "business", optional: true },
      to: { type: "text", label: "To (an account, or reinvest)", optional: true },
      as: asParam("money.manage", "As: an organization whose money or property you manage, only when the input routes what it is paid; left out, it's yours")
    },
    requires: ["level.money >= 3", "params.as == null or may(actor, params.as, params.property == null ? 'money.manage' : 'property.manage')"],
    outcomes: { default: [{ type: "economy.route", args: { party: "self", holding: "=params.holding", property: "=params.property", business: "=params.business", to: "=params.to", by: "actor" } }] },
    duration: "1",
    lexicon: ["reinvest dividends", "send dividends to", "send the rent to"],
    observable: "checks their phone"
  });
  r.worth((ctx, party) => {
    const h = holdingsWorth(r.api, ctx, party);
    const p = propertyWorth(r.api, ctx, party);
    const s = stakeWorth(r.api, ctx, party);
    const v = (optionalQuery(ctx, "vehicles.values")?.(ctx) ?? []).flatMap((x) => {
      const cents2 = Math.round(x.cents * r.api.shareOf(ctx.state, x.vehicle, party) / 100);
      return cents2 > 0 ? [{ label: labelOf(ctx, x.vehicle), cents: cents2, vehicle: true }] : [];
    });
    return { assets: h.assets + p.assets + s.assets + v.reduce((a, l) => a + l.cents, 0), liabilities: 0, lines: [...h.lines, ...p.lines, ...s.lines, ...v] };
  });
  r.view((ctx, party, view) => ({
    investments: investmentsView(r.api, ctx, party, view.detail),
    properties: r.api.feature(ctx, party, "property") || visibleProperties(r.api, ctx, party).some((id2) => r.api.shareOf(ctx.state, id2, party) > 0) ? visibleProperties(r.api, ctx, party).map((id2) => propertyView(r.api, ctx, id2, party, view.flows)) : [],
    alerts: alertsFor(r.api, ctx, party)
  }));
  r.summary((ctx, who) => summaryLines(r.api, ctx, who));
}

