// src/backend/chat-meta-queue.ts
class ChatMetaQueue {
  writes = new Map;
  run(chatId, userId, write) {
    const key = `${userId}\x00${chatId}`;
    const next = (this.writes.get(key) ?? Promise.resolve()).catch(() => {
      return;
    }).then(write);
    this.writes.set(key, next);
    const done = () => {
      if (this.writes.get(key) === next)
        this.writes.delete(key);
    };
    next.then(done, done);
    return next;
  }
}

